#!/usr/bin/env python3
"""Vendors the shell's fonts for the web interface (run on the PC, once, or
when style/theme/Icons.qml gains glyphs; needs fonttools + brotli).

- fonts/pshell-icons.woff2: the Material Design glyphs of "Symbols Nerd Font"
  (MIT / Apache 2.0) that style/theme/Icons.qml names, and ../js/icons.js, the
  name → code point map the web uses (the same names as the shell).
- fonts/AdwaitaSans.woff2, fonts/AdwaitaMono.woff2: Adwaita Sans/Mono (SIL OFL),
  subset to Latin, the variable weight axis kept.

The web works without them too (system fonts, no icons)."""
import json
import re
import sys
from pathlib import Path

from fontTools import subset
from fontTools.ttLib import TTFont

HERE = Path(__file__).resolve().parent
SHELL = HERE.parent.parent.parent
ICONS_QML = SHELL / "style/theme/Icons.qml"
SYMBOLS = Path("/usr/share/fonts/TTF/SymbolsNerdFont-Regular.ttf")
ADWAITA = Path("/usr/share/fonts/Adwaita")


def woff2(source, target, unicodes, keep_layout=True):
    font = TTFont(source)
    options = subset.Options()
    options.flavor = "woff2"
    options.layout_features = ["*"] if keep_layout else []
    options.name_IDs = ["*"]
    options.notdef_outline = True
    options.hinting = False
    sub = subset.Subsetter(options)
    sub.populate(unicodes=unicodes)
    sub.subset(font)
    target.parent.mkdir(parents=True, exist_ok=True)
    font.flavor = "woff2"
    font.save(target)
    print(f"{target.name}: {target.stat().st_size // 1024} KiB", file=sys.stderr)


def icons():
    text = ICONS_QML.read_text()
    glyphs = {}
    for name, char in re.findall(r'"([a-z0-9_]+)":\s*"(.)"', text):
        glyphs[name] = ord(char)
    woff2(SYMBOLS, HERE / "fonts/pshell-icons.woff2", sorted(set(glyphs.values())), keep_layout=False)
    body = ",\n".join(f'\t{json.dumps(k)}: 0x{v:x}' for k, v in sorted(glyphs.items()))
    (HERE.parent / "js/icons.js").write_text(
        "// Generated by vendor/make-fonts.py from style/theme/Icons.qml: the shell's\n"
        "// icon names → code points of vendor/fonts/pshell-icons.woff2.\n"
        f"export const GLYPHS = {{\n{body}\n}};\n"
    )
    print(f"icons: {len(glyphs)}", file=sys.stderr)


def text_fonts():
    latin = list(range(0x20, 0x7F)) + list(range(0xA0, 0x180)) + [
        0x2010, 0x2011, 0x2012, 0x2013, 0x2014, 0x2018, 0x2019, 0x201A, 0x201C, 0x201D, 0x201E,
        0x2022, 0x2026, 0x2032, 0x2033, 0x2039, 0x203A, 0x20AC, 0x2122, 0x2190, 0x2191, 0x2192,
        0x2193, 0x2212, 0x2248, 0x2264, 0x2265, 0x00D7, 0x2715, 0x2713, 0x00B7, 0x2009, 0x202F,
        0x2318, 0x21E7, 0x2325, 0x23CE, 0x232B,
    ]
    woff2(ADWAITA / "AdwaitaSans-Regular.ttf", HERE / "fonts/AdwaitaSans.woff2", latin)
    woff2(ADWAITA / "AdwaitaMono-Regular.ttf", HERE / "fonts/AdwaitaMono.woff2", latin)


if __name__ == "__main__":
    icons()
    text_fonts()
